package com.ai.mall.identity.application.service;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
import com.ai.mall.identity.application.port.*;import com.ai.mall.identity.domain.model.admin.*;import com.ai.mall.identity.domain.repository.AdminUserRepository;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class AdminUserApplicationServiceTest {
 @Test void disablingLastSuperAdminIsRejectedBeforeAggregateIsSaved(){var repo=mock(AdminUserRepository.class);var audit=mock(AuditRecorder.class);when(repo.findById(1)).thenReturn(Optional.of(admin(1)));when(repo.isSuperAdmin(1)).thenReturn(true);when(repo.countEnabledSuperAdmins()).thenReturn(1L);var service=new AdminUserApplicationService(repo,mock(AdminUserQuery.class),mock(PasswordHasher.class),audit,Clock.systemUTC());assertThatThrownBy(()->service.changeStatus(9,1,AdminUserStatus.DISABLED)).hasMessageContaining("last enabled");verify(repo,never()).save(any());verify(audit).record(9,"ADMIN_DISABLE","ADMIN","1","FAILURE","LAST_SUPER_ADMIN");}
 @Test void statusAndPasswordTransitionsAreOwnedByAggregate(){var repo=mock(AdminUserRepository.class);var hasher=mock(PasswordHasher.class);var value=admin(2);when(repo.findById(2)).thenReturn(Optional.of(value));when(hasher.hash("StrongPassword1")).thenReturn("bcrypt");var service=new AdminUserApplicationService(repo,mock(AdminUserQuery.class),hasher,mock(AuditRecorder.class),Clock.systemUTC());service.changeStatus(9,2,AdminUserStatus.DISABLED);service.changePassword(9,2,"StrongPassword1");assertThat(value.status()).isEqualTo(AdminUserStatus.DISABLED);assertThat(value.authVersion()).isEqualTo(3);assertThat(value.permissionVersion()).isEqualTo(2);assertThat(value.passwordHash()).isEqualTo("bcrypt");verify(repo,times(2)).save(value);}
 private static AdminUser admin(long id){return AdminUser.reconstitute(id,"admin","hash","ENABLED",1,1,List.of(),Instant.now(),Instant.now());}
}
